                : change.action() == ClaimAction.VOID ? "void" : null;
        if (perm != null && !settings.allows(claim.getSheetId(), perm, change.user())) {
            throw new ClaimStatusRefusedException("Your role may not " + perm + " a claim");
        }
        if (change.action() == ClaimAction.SETTLE && claim.isDeferred()) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        if (change.action() == ClaimAction.SETTLE && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(change.user())) {
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (change.action() == ClaimAction.APPROVE) {
            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
            }
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
                throw new ClaimStatusRefusedException("Only a steward can approve a pending claim");
            }
        }
        BigDecimal due = null;
        boolean pending = false;
        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            // Figures.due: from the bound figure for an OPEN claim, the live one for a PENDING claim.
            due = figures.due(claim, grade);
            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), claim.getDate());
            if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
            }
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK;
        }
        claim.setStatus(pending ? ClaimStatus.PENDING : change.action().to());
        if (change.action() == ClaimAction.OPEN) {
            claim.setNumber(numbers.next(claim));
            claim.setOpenedBy(change.user());
        }
        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
            claim.setDue(due);
        }
    }
}
package net.officefloor.hq.app.claim;

/** A status change asked of a claim: the status it moves to, the statuses it may move from, and
 *  the audit event it writes. */
public enum ClaimAction {
    OPEN(ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
    SETTLE(ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
    APPROVE(ClaimStatus.SETTLED, "CLAIM_APPROVED", ClaimStatus.PENDING),
    REJECT(ClaimStatus.OPEN, "CLAIM_REJECTED", ClaimStatus.PENDING),
    VOID(ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN, ClaimStatus.PENDING);

    private final ClaimStatus to;
    private final String event;
    private final ClaimStatus[] from;

    ClaimAction(ClaimStatus to, String event, ClaimStatus... from) {
        this.to = to;
        this.event = event;
        this.from = from;
    }

    public ClaimStatus to() { return to; }
    public String event() { return event; }

    public boolean allowedFrom(ClaimStatus status) {
        for (ClaimStatus s : from) {
            if (s == status) return true;
        }
        return false;
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still open: OPEN, or PENDING (handled like an OPEN one: it goes overdue,
     *  bears the late charge and a hold takes it out of the totals). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused status change writes no audit line. */
public class RecordClaimStatusChanged {
    public void record(@Val ClaimStatusChange change, @Val Claim claim, People people, ClaimLog log, Watches watches, Audit audit) {
        log.write(claim, change.user());
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        // A clerk's settle over the clerk limit leaves the claim PENDING: it settles nothing yet.
        boolean pending = change.action() == ClaimAction.SETTLE && claim.getStatus() == ClaimStatus.PENDING;
        boolean fixesDue = !pending && (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE);
        audit.record((pending ? "CLAIM_PENDING" : change.action().event()) + " sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + (fixesDue ? " due=" + (claim.getDue() != null ? claim.getDue().toPlainString() : "n/a") : "")
                + (change.action() == ClaimAction.REJECT ? " reason=" + change.reason() : ""));
        // A watched person's claim settled or approved: a line per watching user, after the claim's own.
        if (fixesDue) watches.notify(claim, person, change.user(), audit);
    }
}
